func:
// node-red-contrib-postgresql returns msg.payload as an array of rows.
// The aggregate query yields exactly one row with a `state` JSON column.
// Unwrap it so the HTTP response body IS the state object directly
// (not [{state: {...}}]).
if (Array.isArray(msg.payload) && msg.payload.length > 0 && msg.payload[0].state) {
  msg.payload = msg.payload[0].state;
} else {
  // Defensive default — return empty shape rather than 500 if tables
  // somehow yielded no row.
  msg.payload = {
    ambients: [],
    slaves: [],
    channels: [],
    rfir_devices: [],
    ambients_rfir_slaves_rel: [],
    ambients_rfir_devices_rel: [],
  };
}
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// valida minimamente e move pra params do postgres
if (!msg.payload || !Array.isArray(msg.payload.devices)) {
    msg.statusCode = 400;
    msg.payload = { error: "missing devices[]" };
    return [null, msg]; // manda pro http response direto
}

msg.params = [ msg.payload ]; // $1 = o JSON inteiro

return [msg, null];

var row = null;

if (msg.payload && msg.payload[0] && msg.payload[0].result) {
    row = msg.payload[0].result;
} else if (msg.payload && msg.payload.rows && msg.payload.rows[0]) {
    row = msg.payload.rows[0].result;
}

if (!row) {
    msg.payload = { error: "no result" };
    msg.statusCode = 500;
} else {
    msg.payload = row;
    msg.statusCode = (row.errors && row.errors.length) ? 207 : 200;
}

return msg;

// clear_all_data_central() returns one row: { result: { removed: {...}, status: 'ok' } }
var row = null;
if (msg.payload && msg.payload[0] && msg.payload[0].result) {
    row = msg.payload[0].result;
} else if (msg.payload && msg.payload.rows && msg.payload.rows[0]) {
    row = msg.payload.rows[0].result;
}
if (!row) {
    msg.payload = { error: "no result" };
    msg.statusCode = 500;
} else {
    msg.payload = row;
    msg.statusCode = 200;
}
msg.headers = { "Content-Type": "application/json" };
return msg;
